 Hello all, i am trying use 'Find' method of excel butr i am getting error:OLE exception from "Microsoft Excel":

Unable to get the Find property of the WorksheetFunction class

Win32::OLE(0.1709) error 0x800a03ec
    in METHOD/PROPERTYGET "Find" at D:\Garg_scripts\KV\demoscript.pl line 44
8<code> use Cwd 'abs_path';
use Win32::OLE;
use Win32::OLE qw(in with);
use Win32::OLE::Const "Microsoft Excel";
$Win32::OLE::Warn = 3;

my $start_run = time();

print"[USAGE]: <demoscript.pl> <.map file path> <Ouput excel path>\n";

print"[INFO]: Executing demoscript.pl V1.0.1.\n";


my $CLEA_Family = $ARGV[0];	



my $Excel =Win32::OLE->new('Excel.Application');

# Open Excel file
my $Book = $Excel->Workbooks->Open($CLEA_Family);

#Make Excel visible
$Excel->{Visible} = 1;

my $Sheet = $Book->Worksheets("IB_MsgSig");

my $worksheetfunction = $Excel->WorksheetFunction();



my $value = $worksheetfunction->Find("IB_MsgSig","E","Go Notifier Customization Availability Flag 2");

print"\n $value";

$Book->Save; #Or $Book->SaveAs("C:\\file_name.xls");
$Book->Close; #or $Excel->Quit;
print"\n[INFO]Timetaken: $run_time [Secs]";</code>
